use mycelix_qualification_verifier_mint_contract::*;

fn b(value: u8) -> [u8; 32] { [value; 32] }
fn d(value: u8) -> Digest { Digest::new(b(value)).unwrap() }
fn n(value: u8) -> Nonce { Nonce::new(b(value)).unwrap() }

fn health_state() -> HealthQualificationStateV1 {
    HealthQualificationStateV1::new(d(1), d(2), 7, 9, d(3), d(4)).unwrap()
}

fn request() -> VerifierMintRequestV1 {
    VerifierMintRequestV1::new(
        TokenProfileV1::GenericAnchorAndSecurityTime,
        d(5), n(6), n(7), health_state(), 1_000, 2_000,
    ).unwrap()
}

fn generic() -> GenericAcceptedAnchorFieldsV1 {
    GenericAcceptedAnchorFieldsV1::new(
        Digest::new(HEALTH_GENERIC_DOMAIN_ID_V1).unwrap(), d(1), 7, d(8), 3,
        Some(d(9)), n(10), d(11), d(12), 2, d(13), d(14), 1_100, 1_950, 0, None,
    ).unwrap()
}

fn security_time() -> HealthSecurityTimeFieldsV1 {
    HealthSecurityTimeFieldsV1::new(3, d(11), d(8), d(15), 1_120, 1_130, 1_900).unwrap()
}

fn statement() -> VerifierMintStatementV1 {
    VerifierMintStatementV1::new(
        &request(), d(16), VerifierIdentityV1::new(d(17), d(18), d(19)), generic(),
        d(20), security_time(), d(21), SignatureSuiteV1::Ed25519MlDsa65, 1_200, 1_800,
    ).unwrap()
}

fn hex(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(HEX[(byte >> 4) as usize] as char);
        out.push(HEX[(byte & 0x0f) as usize] as char);
    }
    out
}

#[test]
fn request_vector_v1_is_frozen() {
    let bytes = request().canonical_bytes();
    assert_eq!(bytes.len(), 313);
    assert_eq!(hex(&bytes), "");
}

#[test]
fn statement_vector_v1_is_frozen() {
    let bytes = statement().canonical_bytes();
    assert_eq!(bytes.len(), 990);
    assert_eq!(hex(&bytes), "");
}
